#include <iostream>
#include <vector>

int main()
{
    std::vector<int> vec_int{3, 1, 4,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           };
    std::vector<double> vec_double{2.5, 7.4, 1.8};

    auto last_element = []<typename T>(const std::vector<T>& v) -> T {
        return v.back();
    };

    int x = last_element(vec_int);
    std::cout << "x = " << x << std::endl;

    double y = last_element(vec_double); 
    std::cout << "y = " << y << std::endl;
}